{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Isradipine, a lipophilic dihydropyridine with extensive first-pass metabolism, has systemic availability of about 17% in healthy volunteers after oral administration, supporting that lipophilic first-pass-cleared molecules can fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Pentazocine has an oral bioavailability of 0.18 in normal subjects, providing another example of a lipophilic drug with first-pass metabolism whose absolute oral bioavailability is below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib, a poorly soluble oral anticancer drug, has an absolute oral bioavailability of 13.9% in fed patients, illustrating solubility-limited low bioavailability relevant to the highly lipophilic query quinone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Rigosertib is reported to have low oral availability requiring continuous intravenous infusion or large oral doses, supporting low F for poorly soluble lipophilic agents.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Rigosertib absolute bioavailability was 35% after a single fasting dose, showing that some poorly soluble drugs can exceed 20% under optimized fasting conditions, but this is less transferable to the query's extreme lipophilicity and high molecular weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Nifedipine has an oral bioavailability of about 45% in humans despite first-pass metabolism, but its much smaller size and better absorption limit transferability to the large polyprenyl quinone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: ubiquinone-9 is an extremely lipophilic, high-molecular-weight polyprenyl benzoquinone with negligible aqueous solubility; analogous poorly soluble/first-pass drugs mostly show F<20%, and no transferable evidence supports F>=20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ubiquinone-9/CoQ9 in the provided records.",
    "No formulation-specific or fed/fasted data for the query molecule.",
    "Available records are structurally distant drugs, limiting quantitative transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

